async function searchAdmin(page: Page, q: string) {
  await page.goto('/catalog');
  await expect(page.getByRole('heading', { level: 1, name: 'קטלוג וניהול' })).toBeVisible();
  await page.getByRole('textbox', { name: /חיפוש מוצר/ }).fill(q);
}

async function asBuyer<T>(browser: Browser, fn: (page: Page) => Promise<T>): Promise<T> {
  const ctx = await browser.newContext({ storageState: auth('buyer'), locale: 'he-IL' });
  const page = await ctx.newPage();
  try {
    return await fn(page);
  } finally {
    await ctx.close();
  }
}

async function buyerSearch(page: Page, q: string) {
  await page.goto('/shop');
  await page.getByRole('searchbox', { name: 'חיפוש מוצר' }).fill(q);
}

/** REST-вызов от имени текущей сессии страницы (ключ anon — из бандла, токен — из localStorage). */
async function rest(page: Page, method: string, pathAndQuery: string) {
  return page.evaluate(async ({ method, pathAndQuery }) => {
    let key: string | null = null;
    for (const src of [...document.scripts].map((s) => s.src).filter(Boolean)) {
      const t = await (await fetch(src)).text();
      const m = t.match(/eyJ[A-Za-z0-9_-]+\.eyJ[A-Za-z0-9_-]+\.[A-Za-z0-9_-]+/);
      if (m) { key = m[0]; break; }
    }
    const tokenKey = Object.keys(localStorage).find((k) => k.includes('auth-token'))!;
    const token = JSON.parse(localStorage.getItem(tokenKey)!).access_token;
    const ref = JSON.parse(atob(key!.split('.')[1])).ref as string;
    const r = await fetch(`https://${ref}.supabase.co/rest/v1/${pathAndQuery}`, {
      method,
      headers: { apikey: key!, Authorization: `Bearer ${token}`, Prefer: 'return=representation' },
    });
    return { status: r.status, body: await r.text() };
  }, { method, pathAndQuery });
}

/** Шторка «סינון ומיון» в /shop (кнопка-иконка рядом с поиском; «נקה סינון» пустого состояния — не она). */
async function openFilterSheet(bp: Page) {
  await bp.getByRole('button', { name: /^(?!נקה).*סינון/ }).first().click();
  const sheet = bp.getByRole('dialog').filter({ hasText: 'סינון ומיון' });
  await expect(sheet).toBeVisible();
  return sheet;
}

/** admin: задать товару категорию (форма редактирования). */
async function setProductCategory(page: Page, name: string) {
  await page.goto(`/catalog/${productId}/edit`);
  const cb = page.getByRole('combobox', { name: 'קטגוריה' });
  await expect(cb.locator('option', { hasText: name })).toHaveCount(1, { timeout: 15_000 });
  const value = await cb.locator('option', { hasText: name }).getAttribute('value');
  await cb.selectOption(value!);
  await page.getByRole('button', { name: 'שמירה', exact: true }).click();
  await expect(page).toHaveURL(/\/catalog$/);
}

async function createCategory(page: Page, name: string, parent?: string) {
  await page.getByRole('button', { name: 'קטגוריה חדשה' }).click();
  await page.getByRole('textbox', { name: /שם קטגוריה/ }).fill(name);
  if (parent) await page.getByRole('combobox', { name: 'קטגוריית אב' }).selectOption({ label: parent });
  await page.getByRole('button', { name: 'שמירה', exact: true }).click();
  await expect(page.getByText(name, { exact: true }).first()).toBeVisible();
}

async function deleteCategory(page: Page, name: string) {
  const label = page.getByText(name, { exact: true }).first();
  if (!(await label.count())) return;
  await catRow(page, name).getByRole('button', { name: 'פעולות' }).first().click();
  const item = page.getByRole('menuitem', { name: /^מחיקה/ });
  if (await item.isDisabled()) { await page.keyboard.press('Escape'); return; }
  await item.click();
  await page.getByRole('dialog').getByRole('button', { name: 'מחיקה' }).click();
  await expect(page.getByText(name, { exact: true })).toHaveCount(0);
}

